const DELETABLE = Symbol.for("myapp.deletable");

class Order {}
Object.defineProperty(Order.prototype, DELETABLE, { value: true });

const isDeletable = (o) => typeof o === "object" && o !== null && DELETABLE in o;

const validated = new WeakSet();

class SafeHtml {
  constructor(html) { this.html = sanitize(html); validated.add(this); }
}

export function assertSafe(el) {
  if (!validated.has(el)) throw new TypeError("unvalidated");
}
